<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import ConfirmationModal from '@/Components/ConfirmationModal.vue';
import InputError from '@/Components/InputError.vue';
import ValidationSummary from '@/Components/ValidationSummary.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';

const props = defineProps<{ event: any; party: any; rsvpAdditionalGuests: any[]; partyDates: any; rsvpUrl: string; canManage: boolean; memberTypes: string[] }>();
const partyForm = useForm({ name: props.party.name, primary_contact_name: props.party.primary_contact_name || '', email: props.party.email || '', phone: props.party.phone || '', maximum_party_size: props.party.maximum_party_size, table_name: props.party.table_name || '', notes: props.party.notes || '' });
const memberForm = useForm({ first_name: '', last_name: '', member_type: 'adult', notes: '' });
const editingMember = ref<any>(null);
const pendingMember = ref<any>(null);
const memberSubmit = () => editingMember.value ? memberForm.put(route('events.guests.members.update', [props.event.id, props.party.id, editingMember.value.id]), { onSuccess: () => { editingMember.value = null; memberForm.reset(); } }) : memberForm.post(route('events.guests.members.store', [props.event.id, props.party.id]), { onSuccess: () => memberForm.reset() });
const editMember = (member: any) => { editingMember.value = member; memberForm.first_name = member.first_name; memberForm.last_name = member.last_name || ''; memberForm.member_type = member.member_type; memberForm.notes = member.notes || ''; };
const cancelMemberEdit = () => { editingMember.value = null; memberForm.reset(); };
const removeMember = () => router.delete(route('events.guests.members.destroy', [props.event.id, props.party.id, pendingMember.value.id]), { onFinish: () => pendingMember.value = null });
</script>

<template>
    <Head :title="party.name" />
    <AuthenticatedLayout>
        <template #header><div class="flex items-center justify-between gap-3"><div><h2 class="text-xl font-semibold">{{ party.name }}</h2><p class="text-sm text-gray-600">Invitation party</p></div><div class="flex gap-2"><Link :href="route('events.guests.index', event.id)" class="rounded border border-gray-300 px-3 py-2 text-sm">Back to Guest List</Link><a v-if="canManage" href="#party-edit" class="rounded border border-gray-300 px-3 py-2 text-sm">Edit Party</a><a v-if="canManage" href="#manage-members" class="rounded bg-indigo-600 px-3 py-2 text-sm text-white">Manage Members</a></div></div></template>
        <div class="mx-auto max-w-5xl space-y-5 p-6"><section v-if="canManage" class="rounded bg-white p-5 shadow"><h3 class="mb-2 text-lg font-semibold">RSVP link</h3><div class="flex gap-2"><input :value="rsvpUrl" readonly class="w-full rounded border-gray-300 bg-gray-50" /><a :href="rsvpUrl" target="_blank" class="rounded border border-gray-300 px-3 py-2 text-sm">Open</a><button @click="router.patch(route('events.guests.rsvp-token', [event.id, party.id]))" class="rounded border border-gray-300 px-3 py-2 text-sm">Regenerate</button></div></section><section id="party-edit" class="rounded bg-white p-5 shadow"><h3 class="mb-4 text-lg font-semibold">{{ canManage ? 'Edit party' : 'Party details' }}</h3><dl v-if="!canManage" class="grid gap-4 sm:grid-cols-2"><div><dt class="text-sm text-gray-500">Party name</dt><dd>{{ party.name }}</dd></div><div><dt class="text-sm text-gray-500">Maximum party size</dt><dd>{{ party.maximum_party_size }}</dd></div><div><dt class="text-sm text-gray-500">Primary contact</dt><dd>{{ party.primary_contact_name || 'Not provided' }}</dd></div><div><dt class="text-sm text-gray-500">Email</dt><dd>{{ party.email || 'Not provided' }}</dd></div><div><dt class="text-sm text-gray-500">Phone</dt><dd>{{ party.phone || 'Not provided' }}</dd></div><div><dt class="text-sm text-gray-500">Table</dt><dd>{{ party.table_name || 'Not assigned' }}</dd></div><div class="sm:col-span-2"><dt class="text-sm text-gray-500">Notes</dt><dd class="whitespace-pre-line">{{ party.notes || 'Not provided' }}</dd></div></dl><form v-else @submit.prevent="partyForm.put(route('events.guests.update', [event.id, party.id]))" class="grid gap-3 sm:grid-cols-2"><div><label class="mb-1 block text-sm">Party / invitation name</label><input v-model="partyForm.name" required class="w-full rounded border-gray-300" /><InputError :message="partyForm.errors.name" class="mt-1" /></div><div><label class="mb-1 block text-sm">Maximum party size</label><input v-model="partyForm.maximum_party_size" type="number" min="1" required class="w-full rounded border-gray-300" /><InputError :message="partyForm.errors.maximum_party_size" class="mt-1" /></div><div><label class="mb-1 block text-sm">Primary contact name</label><input v-model="partyForm.primary_contact_name" class="w-full rounded border-gray-300" /></div><div><label class="mb-1 block text-sm">Email</label><input v-model="partyForm.email" type="email" class="w-full rounded border-gray-300" /><InputError :message="partyForm.errors.email" class="mt-1" /></div><div><label class="mb-1 block text-sm">Phone</label><input v-model="partyForm.phone" class="w-full rounded border-gray-300" /></div><div><label class="mb-1 block text-sm">Table</label><input v-model="partyForm.table_name" class="w-full rounded border-gray-300" /></div><div class="sm:col-span-2"><label class="mb-1 block text-sm">Internal notes</label><textarea v-model="partyForm.notes" class="w-full rounded border-gray-300" /></div><div class="sm:col-span-2"><ValidationSummary :errors="partyForm.errors" /></div><button class="w-fit rounded bg-indigo-600 px-3 py-2 text-white">Save party</button></form></section>

            <section v-if="canManage" id="manage-members" class="rounded bg-white p-5 shadow"><h3 class="mb-3 text-lg font-semibold">{{ editingMember ? 'Edit member' : 'Manage members' }}</h3><form @submit.prevent="memberSubmit" class="grid gap-3 sm:grid-cols-2"><div><label class="mb-1 block text-sm">First name</label><input v-model="memberForm.first_name" required class="w-full rounded border-gray-300" /><InputError :message="memberForm.errors.first_name" class="mt-1" /></div><div><label class="mb-1 block text-sm">Last name</label><input v-model="memberForm.last_name" class="w-full rounded border-gray-300" /></div><div><label class="mb-1 block text-sm">Classification</label><select v-model="memberForm.member_type" class="w-full rounded border-gray-300"><option v-for="type in memberTypes" :key="type" :value="type" class="capitalize">{{ type }}</option></select></div><div><label class="mb-1 block text-sm">Notes</label><input v-model="memberForm.notes" class="w-full rounded border-gray-300" /></div><div class="sm:col-span-2"><ValidationSummary :errors="memberForm.errors" /></div><div class="flex gap-3"><button class="rounded bg-indigo-600 px-3 py-2 text-white">{{ editingMember ? 'Save member' : 'Add member' }}</button><button v-if="editingMember" type="button" @click="cancelMemberEdit" class="text-gray-600">Cancel</button></div></form></section>

            <section class="overflow-x-auto rounded bg-white shadow"><div class="p-5"><h3 class="text-lg font-semibold">Members</h3><p class="text-sm text-gray-500">{{ party.members.length }} of {{ party.maximum_party_size }} listed member slots used.</p></div><table class="min-w-full text-left text-sm"><thead class="bg-gray-50 text-gray-600"><tr><th class="p-3">Name</th><th class="p-3">Classification</th><th class="p-3">Notes</th><th v-if="canManage" class="p-3"></th></tr></thead><tbody><tr v-for="member in party.members" :key="member.id" class="border-t"><td class="p-3">{{ member.first_name }} {{ member.last_name }}</td><td class="p-3 capitalize">{{ member.member_type }}</td><td class="p-3">{{ member.notes || 'Not provided' }}</td><td v-if="canManage" class="p-3"><button @click="editMember(member)" class="text-indigo-600">Edit</button><button @click="pendingMember = member" class="ml-3 text-red-600">Remove</button></td></tr></tbody></table><p v-if="!party.members.length" class="p-5 text-gray-600">No members have been listed yet.</p></section>
            <section class="overflow-x-auto rounded bg-white shadow"><div class="p-5"><h3 class="text-lg font-semibold">RSVP Additional Guests</h3><p class="text-sm text-gray-500">These guests belong to the current RSVP response and are not permanent Party Members.</p></div><table v-if="rsvpAdditionalGuests.length" class="min-w-full text-left text-sm"><thead class="bg-gray-50 text-gray-600"><tr><th class="p-3">Name</th><th class="p-3">Classification</th><th class="p-3">Attendance</th><th class="p-3">Meal</th><th class="p-3">Dietary note</th><th class="p-3">Source</th></tr></thead><tbody><tr v-for="(guest, index) in rsvpAdditionalGuests" :key="index" class="border-t"><td class="p-3">{{ guest.first_name }} {{ guest.last_name }}</td><td class="p-3 capitalize">{{ guest.member_type }}</td><td class="p-3">{{ guest.is_attending ? 'Attending' : 'Not attending' }}</td><td class="p-3">{{ guest.is_attending && guest.meal ? guest.meal : 'None' }}</td><td class="p-3">{{ guest.is_attending && guest.dietary_note ? guest.dietary_note : 'None' }}</td><td class="p-3">Additional guest</td></tr></tbody></table><p v-else class="p-5 text-gray-600">No additional RSVP guests.</p></section>
            <section class="rounded bg-white p-5 shadow"><h3 class="mb-3 text-lg font-semibold">System information</h3><dl class="grid gap-4 sm:grid-cols-2"><div><dt class="text-sm text-gray-500">Created</dt><dd>{{ partyDates.created_at }}</dd></div><div><dt class="text-sm text-gray-500">Last updated</dt><dd>{{ partyDates.updated_at }}</dd></div></dl></section>
        </div>
        <ConfirmationModal :show="!!pendingMember" title="Remove party member?" message="This member will be removed from the active guest list." confirm-label="Remove member" @close="pendingMember = null" @confirm="removeMember" />
    </AuthenticatedLayout>
</template>
